'use server'

import { updateTag } from 'next/cache'
import { insertPost } from '@/lib/posts-store'

export async function createPost(formData: FormData) {
  const titleValue = formData.get('title')
  const contentValue = formData.get('content')

  if (typeof titleValue !== 'string' || typeof contentValue !== 'string') {
    throw new Error('A title and post content are required.')
  }

  const title = titleValue.trim()
  const content = contentValue.trim()

  if (!title || !content) {
    throw new Error('A title and post content are required.')
  }

  await insertPost({ title, content })

  // Expire the cached list before this Server Action rerenders the page.
  updateTag('posts')
}
import { randomUUID } from 'node:crypto'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

type PostsGlobal = typeof globalThis & {
  __postsForExample?: Post[]
}

function getPostsStore(): Post[] {
  const globalWithPosts = globalThis as PostsGlobal
  globalWithPosts.__postsForExample ??= []
  return globalWithPosts.__postsForExample
}

export async function insertPost(input: Pick<Post, 'title' | 'content'>) {
  const post: Post = {
    id: randomUUID(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }

  getPostsStore().unshift(post)
  return post
}

export async function readPosts(): Promise<Post[]> {
  return getPostsStore().map((post) => ({ ...post }))
}
